create extension if not exists pgcrypto;
create table members (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users on delete cascade, name text not null, created_at timestamptz default now());
create table medicines (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users on delete cascade, member_id uuid references members on delete cascade, name text not null, dose text, frequency text, duration text, created_at timestamptz default now());
create table prescriptions (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users on delete cascade, member_id uuid references members on delete cascade, hospital text, doctor text, date date not null, follow_up date, medicines jsonb default '[]', file_path text, created_at timestamptz default now());
create table reports (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users on delete cascade, member_id uuid references members on delete cascade, title text not null, type text, date date, file_path text, notes text, created_at timestamptz default now());
create table visits (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users on delete cascade, member_id uuid references members on delete cascade, reason text not null, doctor text, hospital text, date date not null, created_at timestamptz default now());
create table messages (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users on delete cascade, name text, email text, message text not null, created_at timestamptz default now());
insert into storage.buckets (id, name, public) values ('records', 'records', false) on conflict do nothing;
